window.CLASSES=[{"id": 1, "title": "Conozco mi computadora", "subtitle": "Exploramos, identificamos y cuidamos la tecnología", "purpose": "Reconocer las partes de la computadora y entender para qué sirven en nuestra vida diaria.", "objectives": ["Identificar los componentes de la computadora.", "Explicar la función de cada parte.", "Valorar la tecnología en la escuela, en casa y en la comunidad."], "materials": ["Computadora o imágenes", "Proyector o pantalla", "Cuaderno y lápiz"], "concepts": [["Monitor", "Muestra imágenes, textos y videos."], ["Teclado", "Permite escribir letras, números y dar instrucciones."], ["Mouse", "Mueve el puntero y permite seleccionar y hacer clic."], ["Bocinas", "Reproducen sonidos."], ["Gabinete y CPU", "El gabinete o torre contiene componentes. Dentro se encuentra el procesador o CPU, que ejecuta instrucciones."], ["Otros dispositivos", "Podemos conectar una cámara, un micrófono o una impresora."], ["¿Para qué sirve?", "Estudiar, investigar, dibujar, crear documentos, jugar, comunicarnos y explorar."], ["Cuidemos el equipo", "Mantén el equipo limpio. No comas ni bebas cerca. Cuida los cables y apágalo correctamente."]], "steps": ["Observa la computadora de tu escuela o la infografía.", "Identifica sus partes.", "Escribe en tu cuaderno cinco partes y para qué sirve cada una.", "Dibuja tu computadora y señala sus partes.", "Comparte tu dibujo con un compañero."], "questions": ["¿Qué parte de la computadora te parece más importante? ¿Por qué?", "¿Qué pasaría si no tuviéramos computadora?", "¿En qué actividades de tu vida diaria podrías usarla?", "¿Cómo podemos cuidar la tecnología de nuestra escuela?"], "learned": ["Reconozco las partes de la computadora.", "Identifico sus funciones.", "Entiendo su importancia.", "Aprendo a cuidarla.", "Trabajo en equipo."], "home": "Busca en casa una computadora, tableta o celular. Identifica tres partes y explica para qué sirven. Puedes dibujar o pegar imágenes.", "practice": "Une cada parte con su función", "kind": "quiz", "extra": "En tu imagen aparece «CPU o torre». Para explicarlo con precisión: la torre es el gabinete; la CPU es el procesador que está dentro. La infografía original se conserva íntegra.", "quiz": [["¿Qué parte muestra imágenes y textos?", ["Monitor", "Teclado", "Bocinas"], 0, "El monitor muestra lo que la computadora produce."], ["¿Qué usas para escribir?", ["Mouse", "Teclado", "Impresora"], 1, "Las teclas permiten escribir letras, números y signos."], ["¿Qué reproduce sonidos?", ["Bocinas", "Monitor", "Gabinete"], 0, "Las bocinas son una salida de sonido."], ["¿Cómo cuidas el equipo?", ["Bebo junto al teclado", "Tiro de los cables", "Mantengo comida y bebida lejos"], 2, "Los líquidos y la comida pueden dañar el equipo."]], "evidence": "Dibujo con cinco partes y sus funciones."}, {"id": 2, "title": "Entrada, proceso y salida", "subtitle": "Así trabaja mi computadora", "purpose": "Comprender cómo la computadora recibe datos, los procesa y nos entrega un resultado.", "objectives": ["Identificar dispositivos de entrada, proceso y salida.", "Reconocer ejemplos en la vida diaria.", "Valorar la importancia de la tecnología."], "materials": ["Computadora o tableta", "Cuaderno y lápiz", "Proyector opcional"], "concepts": [["Entrada", "Introducimos datos con el teclado, mouse, micrófono o pantalla táctil."], ["Proceso", "La computadora trabaja con los datos, ejecuta programas y sigue instrucciones."], ["Salida", "Obtenemos resultados: el monitor muestra, las bocinas reproducen y la impresora imprime."], ["Un ejemplo", "Escribes 2 + 3; el programa realiza la operación; la pantalla muestra 5."], ["Una pantalla táctil", "Puede mostrar información y recibir tus toques: cumple funciones de entrada y salida."]], "steps": ["Observa los dispositivos de tu computadora.", "Clasifícalos en entrada, proceso o salida.", "Escribe dos ejemplos de cada etapa en tu cuaderno.", "Comparte tus respuestas con un compañero.", "Escribe una palabra y observa cómo aparece en el monitor."], "questions": ["¿Qué dispositivos usamos para escribir un texto?", "¿Qué parte procesa la información?", "¿Qué pasaría si no tuviéramos un monitor?", "Da un ejemplo de entrada, proceso y salida en la vida diaria.", "¿Cómo nos ayuda este proceso en la escuela?"], "learned": ["Identifico entrada, proceso y salida.", "Comprendo cómo trabaja la computadora.", "Reconozco ejemplos cotidianos.", "Trabajo en equipo."], "home": "Busca un proceso similar en un microondas, una lavadora o un videojuego. Dibuja su entrada, proceso y salida.", "practice": "Clasifica: entrada, proceso o salida", "kind": "classify", "extra": "", "quiz": [], "evidence": "Diagrama de entrada, proceso y salida."}, {"id": 3, "title": "El mouse y las ventanas", "subtitle": "Exploramos, hacemos clic y navegamos", "purpose": "Usar el mouse y reconocer las partes de una ventana para navegar y realizar tareas de forma segura.", "objectives": ["Identificar las acciones básicas del mouse.", "Reconocer títulos, botones y menús de una ventana.", "Abrir, cerrar, minimizar y cambiar entre ventanas.", "Desarrollar destrezas de navegación."], "materials": ["Computadora", "Mouse o touchpad", "Sistema operativo", "Cuaderno y lápiz", "Proyector opcional"], "concepts": [["Botón izquierdo", "Selecciona y permite hacer clic."], ["Rueda de desplazamiento", "Permite subir o bajar en una página."], ["Botón derecho", "Muestra un menú de opciones."], ["Acciones básicas", "Un clic selecciona; un doble clic puede abrir archivos; arrastrar mueve objetos; desplazar permite recorrer la página."], ["Partes de una ventana", "La barra de título muestra su nombre, el menú reúne opciones y el área de trabajo es donde realizas actividades."], ["Botones de la ventana", "Minimizar la oculta; maximizar la hace grande; cerrar termina esa ventana. El programa puede seguir abierto si tiene otras ventanas."]], "steps": ["Abre un programa como Paint, Word o un navegador.", "Practica clic y doble clic.", "Arrastra una carpeta a otra ubicación de práctica.", "Minimiza, maximiza y cierra una ventana.", "Cambia entre dos ventanas abiertas."], "questions": ["¿Para qué nos sirve el mouse?", "¿Qué pasa si hacemos doble clic?", "¿Qué es la barra de título?", "¿Cómo podemos mover una ventana?", "¿Cuándo usamos varias ventanas al mismo tiempo?"], "learned": ["Uso correctamente el mouse.", "Reconozco las partes de una ventana.", "Practico acciones básicas.", "Navego entre ventanas.", "Trabajo con más confianza."], "home": "", "practice": "Circuito del mouse", "kind": "mouse", "extra": "", "quiz": [], "evidence": "Demostración de clic, desplazamiento y manejo de ventanas."}, {"id": 4, "title": "El teclado: escribo y aprendo", "subtitle": "Cada tecla es una gran oportunidad para crear ideas", "purpose": "Usar el teclado para escribir letras, números y signos, desarrollando autonomía y habilidades de escritura.", "objectives": ["Identificar las partes del teclado.", "Conocer teclas especiales.", "Escribir palabras y oraciones sencillas.", "Mejorar coordinación y precisión."], "materials": ["Computadora", "Teclado", "Cuaderno y lápiz", "Procesador de textos o práctica de esta página"], "concepts": [["Tipos de teclas", "Hay letras, números, teclas de función como F1 y teclas de control como Esc."], ["Enter", "Acepta una acción o pasa a la siguiente línea según el programa."], ["Backspace", "Borra el carácter anterior al cursor."], ["Shift", "Permite escribir una mayúscula al mantenerla presionada junto con una letra."], ["Tab", "Mueve el foco o inserta una tabulación según el programa."], ["Espacio", "Deja un espacio entre palabras."]], "steps": ["Abre un procesador de textos o la práctica de esta clase.", "Escribe tu nombre en tu cuaderno o archivo local.", "Escribe una oración sobre tu escuela.", "Usa mayúsculas y signos de puntuación.", "Guarda tu archivo."], "questions": ["¿Qué tecla usamos para borrar?", "¿Cómo escribimos una letra mayúscula?", "¿Para qué sirve Enter?", "¿Qué pasaría si no tuviéramos teclado?", "¿Cuándo es importante escribir en la computadora?"], "learned": ["Reconozco las partes del teclado.", "Conozco teclas importantes.", "Escribo palabras y oraciones.", "Practico con precisión.", "Comunico mis ideas."], "home": "Escribe un párrafo de tres o cuatro oraciones sobre lo que te gusta de tu escuela. Guárdalo y, si puedes, imprímelo.", "practice": "Escribe con calma", "kind": "typing", "extra": "", "quiz": [], "evidence": "Oraciones con mayúsculas, espacios y signos."}, {"id": 5, "title": "Mis archivos y carpetas", "subtitle": "Organizo mi información, encuentro lo que necesito", "purpose": "Crear, organizar, nombrar, copiar, mover y eliminar archivos y carpetas para mantener la información ordenada.", "objectives": ["Reconocer archivos y carpetas.", "Crear carpetas y subcarpetas.", "Guardar, renombrar, mover y copiar archivos.", "Mantener una organización sencilla."], "materials": ["Computadora", "Sistema operativo", "Cuaderno y lápiz", "Archivos de ejemplo", "Proyector opcional"], "concepts": [["Archivo", "Información guardada, como un texto, una imagen, un audio o un video."], ["Nombre y extensión", "El nombre ayuda a reconocerlo. La extensión, como .jpg o .mp3, indica su tipo; algunos sistemas la ocultan."], ["Carpeta", "Contiene archivos y otras carpetas. Puedes organizarlas por tema o proyecto."], ["Crear y renombrar", "Crear hace una carpeta nueva. Renombrar cambia su nombre o el de un archivo."], ["Copiar y mover", "Copiar deja el original y crea otra copia. Mover cambia el archivo de lugar."], ["Eliminar", "Quita un archivo. Practica solo con archivos de ejemplo que puedas borrar."]], "steps": ["Crea una carpeta en el Escritorio.", "Nómbrala con tu nombre.", "Dentro, crea dos subcarpetas: Tareas e Imágenes.", "Guarda un archivo de texto en Tareas.", "Copia una imagen a Imágenes.", "Cambia el nombre de un archivo.", "Mueve un archivo entre carpetas.", "Elimina un archivo de prueba."], "questions": ["¿Para qué nos sirven las carpetas?", "¿Qué pasaría si todo estuviera en el Escritorio?", "¿Cuál es la diferencia entre copiar y mover?", "¿Cuándo usamos archivos y carpetas en la vida diaria?"], "learned": ["Reconozco archivos y carpetas.", "Creo y organizo carpetas.", "Guardo, renombro, copio y muevo archivos.", "Mantengo mi espacio digital ordenado."], "home": "Crea una carpeta llamada Mi escuela con tres subcarpetas: Tareas, Dibujos y Proyectos. Guarda al menos un archivo en cada una.", "practice": "Organiza tu carpeta", "kind": "files", "extra": "", "quiz": [], "evidence": "Carpeta organizada con archivos de ejemplo."}, {"id": 6, "title": "Navego en Internet", "subtitle": "Busco, exploro y aprendo con seguridad", "purpose": "Buscar información en Internet utilizando un navegador, identificando fuentes confiables y aplicando buenas prácticas.", "objectives": ["Conocer Internet y el navegador web.", "Realizar búsquedas de información.", "Identificar fuentes confiables.", "Aplicar seguridad en línea.", "Explorar recursos educativos."], "materials": ["Computadora", "Conexión a Internet para búsquedas reales", "Navegador web", "Cuaderno y lápiz", "Proyector opcional"], "concepts": [["Internet", "Es una red mundial que conecta dispositivos y permite acceder a información y comunicarnos."], ["Navegador", "Programa para abrir páginas, como Chrome, Edge, Firefox o Safari."], ["Buscador", "Servicio que ayuda a encontrar información. Navegador y buscador tienen funciones diferentes."], ["Palabras clave", "Escribe palabras claras y específicas. Por ejemplo: animales en peligro de extinción en México."], ["Fuentes confiables", "Revisa quién publica, la fecha, el propósito y compara con otras fuentes."], ["Conexión y confianza", "HTTPS protege la conexión. Por sí solo no garantiza que el contenido sea verdadero ni que el sitio sea honesto. El dominio tampoco basta."], ["Navega con cuidado", "No compartas datos personales; pide ayuda si algo es extraño; respeta a otras personas y cierra tu sesión al terminar."]], "steps": ["Abre tu navegador web.", "Busca un tema que te interese, como animales o ciencia.", "Compara al menos dos fuentes con ayuda de tu docente.", "Elige una imagen permitida para tu actividad; guárdala y anota su fuente.", "Escribe tres cosas nuevas que aprendiste."], "questions": ["¿Qué es Internet?", "¿Qué es un navegador?", "¿Cómo sabes si una fuente es confiable?", "¿Qué debes evitar al navegar?", "¿Para qué te gustaría usar Internet?"], "learned": ["Conozco qué es Internet.", "Uso un navegador.", "Realizo búsquedas.", "Comparo fuentes.", "Navego de forma responsable."], "home": "", "practice": "Elige una buena búsqueda", "kind": "quiz", "extra": "El candado y HTTPS hablan de la conexión, no de la veracidad. Tampoco .org, .edu o un logotipo garantizan confianza. Usa autoría, fecha y contraste. La práctica interna es una simulación y no abre búsquedas reales.", "quiz": [["Quieres aprender sobre jaguares de México. ¿Qué búsqueda es más precisa?", ["Cosas", "Animales bonitos", "Hábitat del jaguar en México"], 2, "Las palabras específicas ayudan a encontrar información relacionada."], ["¿Cuál es un navegador?", ["Chrome", "Un cuaderno", "Una carpeta"], 0, "Chrome es un programa para abrir páginas web."], ["Una página tiene HTTPS. ¿Ya sabes que todo es verdadero?", ["Sí, siempre", "No; debo revisar la fuente", "Sí, si tiene colores"], 1, "HTTPS protege la conexión. Aún debemos revisar autoría y comparar."], ["Encuentras una noticia sorprendente. ¿Qué haces?", ["La comparto sin leer", "Reviso autoría, fecha y otras fuentes", "Creo cualquier imagen"], 1, "Comparar fuentes ayuda a detectar información equivocada."]], "evidence": "Tres aprendizajes con sus fuentes."}, {"id": 7, "title": "Uso de programas", "subtitle": "Creo, practico y desarrollo habilidades digitales", "purpose": "Utilizar programas básicos para realizar tareas escolares y proyectos creativos.", "objectives": ["Reconocer distintos programas.", "Abrir, usar y guardar un archivo.", "Trabajar con un procesador de textos.", "Explorar presentaciones.", "Desarrollar creatividad y autonomía."], "materials": ["Computadora", "Procesador de textos o programa de presentaciones", "Cuaderno y lápiz", "Proyector opcional"], "concepts": [["Programa", "Aplicación para realizar tareas: escribir, dibujar, presentar o calcular."], ["Cada tarea, su herramienta", "Un procesador trabaja con textos; las presentaciones usan diapositivas; una hoja de cálculo organiza datos; un programa de dibujo crea imágenes."], ["Abrir un programa", "Localiza la aplicación en el menú o buscador de tu equipo y abre su icono."], ["Guardar", "Usa Guardar o Guardar como; elige una carpeta y un nombre que reconozcas."], ["Dar formato", "Puedes cambiar tamaño, negritas, cursivas y colores para que el texto se lea mejor."], ["Presentar", "Crea un título y agrega imágenes y texto. Guarda tu trabajo."]], "steps": ["Abre un programa de tu preferencia.", "Crea un documento sobre un tema libre o una presentación de al menos tres diapositivas.", "En el documento practica tamaño de letra, negrita, cursiva y color.", "Guarda tu trabajo con un nombre claro.", "Muéstralo a tu docente."], "questions": ["¿Qué programas conoces?", "¿Para qué sirve un procesador de textos?", "¿Cuándo usarías una presentación?", "¿Qué pasa si no guardas?", "¿Qué otros programas te gustaría aprender?"], "learned": ["Reconozco qué es un programa.", "Abro programas básicos.", "Creo y guardo archivos.", "Uso textos y presentaciones.", "Desarrollo creatividad."], "home": "", "practice": "Un programa para cada tarea", "kind": "quiz", "extra": "", "quiz": [["Vas a escribir una ficha de un animal. ¿Qué herramienta elegirías?", ["Procesador de textos", "Reproductor de música", "Papelera"], 0, "Un procesador permite escribir y dar formato."], ["Quieres explicar un tema con diapositivas. ¿Qué usas?", ["Calculadora", "Programa de presentaciones", "Carpeta vacía"], 1, "Las presentaciones organizan ideas en diapositivas."], ["Para conservar tu trabajo debes…", ["Cerrar sin revisar", "Apagar inmediatamente", "Guardar con un nombre claro"], 2, "Guardar permite volver a abrir el archivo."], ["¿Para qué usarías una hoja de cálculo?", ["Organizar datos en filas y columnas", "Reproducir una película", "Mover el mouse"], 0, "Las hojas de cálculo trabajan con datos y operaciones."]], "evidence": "Documento o presentación guardada."}, {"id": 8, "title": "Seguridad en la computadora", "subtitle": "Cuido mi información, navego seguro", "purpose": "Reconocer riesgos y proteger nuestra información, dispositivos y privacidad al usar la computadora e Internet.", "objectives": ["Identificar riesgos en Internet.", "Aplicar medidas de seguridad.", "Comprender qué hace fuerte una contraseña.", "Reconocer información confiable.", "Compartir con responsabilidad."], "materials": ["Computadora", "Cuaderno y lápiz", "Infografía de la clase", "Proyector opcional"], "concepts": [["Seguridad digital", "Acciones para cuidar nuestra información, dispositivos y privacidad."], ["Riesgos", "Mensajes sospechosos, páginas falsas, personas desconocidas, descargas no seguras y premios demasiado buenos para ser verdad."], ["Contraseñas", "Conviene que sean largas, únicas y difíciles de adivinar. No uses datos personales ni copies ejemplos publicados. Trabaja con ejemplos ficticios."], ["Información confiable", "Revisa autoría, fecha y compara fuentes antes de creer y compartir."], ["Datos personales", "Cuida nombre completo, dirección, teléfono, fotos, ubicación y nombre de la escuela."], ["Pide ayuda", "Si recibes un mensaje extraño, detente y habla con una persona adulta de confianza."]], "steps": ["Responde la práctica de seguridad digital.", "En tu cuaderno inventa un ejemplo de contraseña solo para practicar; nunca uses una contraseña real.", "Identifica situaciones seguras y peligrosas.", "Escribe tres consejos para estar seguro en Internet.", "Comparte tus ideas con el grupo."], "questions": ["¿Por qué necesitamos una contraseña segura?", "¿Qué harías ante un mensaje de una persona desconocida?", "¿Cómo sabes si una página es confiable?", "¿Qué información personal debes cuidar?", "¿Cómo ayudarías a tu familia a usar Internet con seguridad?"], "learned": ["Identifico riesgos.", "Reconozco contraseñas más fuertes.", "Comparo información.", "Protejo datos personales.", "Actúo con responsabilidad."], "home": "", "practice": "Detectives de la seguridad", "kind": "quiz", "extra": "Actualización para la explicación: prioriza contraseñas largas, únicas e impredecibles. No reutilices el ejemplo de la lámina. Esta plataforma no solicita ni guarda contraseñas.", "quiz": [["Un desconocido pide tu dirección. ¿Qué haces?", ["La envío", "No la comparto y pido ayuda", "Le envío mi ubicación"], 1, "Tu dirección es un dato personal. Acude a un adulto de confianza."], ["¿Qué característica ayuda a una contraseña?", ["Ser igual en todas las cuentas", "Usar mi nombre", "Ser larga, única y difícil de adivinar"], 2, "Evita datos personales, ejemplos públicos y contraseñas reutilizadas."], ["Un anuncio dice que ganaste un premio y debes descargar algo. ¿Qué haces?", ["Lo descargo", "Me detengo y consulto a un adulto", "Lo comparto con todos"], 1, "Los premios inesperados pueden esconder engaños."], ["¿Qué debes hacer antes de compartir una noticia?", ["Comparar fuentes y revisar quién publica", "Ver solo el título", "Contar los colores"], 0, "Revisar autoría y contrastar ayuda a compartir con responsabilidad."]], "evidence": "Tres consejos de seguridad y explicación de un caso."}, {"id": 9, "title": "Manejo de archivos", "subtitle": "Guardo, organizo y encuentro mi información", "purpose": "Practicar la organización, copia, traslado, eliminación y recuperación de archivos con mayor autonomía.", "objectives": ["Identificar archivos y carpetas.", "Crear y nombrar carpetas.", "Guardar en el lugar correcto.", "Mover, copiar y eliminar archivos.", "Mantener orden digital."], "materials": ["Computadora", "Cuaderno y lápiz", "Archivos de ejemplo", "Proyector opcional"], "concepts": [["Recuperamos lo aprendido", "Los archivos guardan información y las carpetas nos ayudan a organizarla."], ["Crear una carpeta", "En Windows: clic derecho en un espacio vacío, Nuevo, Carpeta; escribe un nombre y presiona Enter. En otros sistemas la opción puede estar en el menú Archivo."], ["Guardar, mover y copiar", "Guardar almacena el trabajo; mover cambia su ubicación; copiar conserva el original y crea otra copia."], ["Papelera", "Muchos archivos eliminados pasan a la Papelera. Si siguen allí, puedes restaurarlos. Algunas eliminaciones son permanentes."], ["Un buen nombre", "Elige nombres claros y fáciles de recordar. Organiza por materia o proyecto."]], "steps": ["Crea una carpeta con tu nombre.", "Dentro crea tres subcarpetas: Escuela, Dibujos y Juegos.", "Guarda al menos tres archivos de ejemplo en cada subcarpeta.", "Mueve un archivo entre carpetas.", "Elimina un archivo de prueba y recupéralo de la Papelera."], "questions": ["¿Qué es un archivo?", "¿Qué es una carpeta?", "¿Por qué es importante organizar?", "¿Qué pasaría si no tuviéramos carpetas?", "¿Cuándo ayuda el orden digital?"], "learned": ["Identifico archivos y carpetas.", "Creo y nombro carpetas.", "Guardo, muevo, copio y elimino.", "Reconozco el valor del orden.", "Recupero archivos de prueba."], "home": "", "practice": "Mueve, copia y recupera", "kind": "files", "extra": "", "quiz": [], "evidence": "Carpetas organizadas y archivo de prueba recuperado."}, {"id": 10, "title": "Creo mi presentación", "subtitle": "Comunico mis ideas con diapositivas", "purpose": "Crear una presentación digital clara, visual y creativa utilizando imágenes, texto y diseño.", "objectives": ["Conocer qué es una presentación.", "Crear y organizar diapositivas.", "Agregar texto e imágenes.", "Aplicar un diseño legible.", "Guardar y presentar el trabajo."], "materials": ["Computadora", "Programa de presentaciones", "Cuaderno y lápiz", "Imágenes opcionales", "Mouse o touchpad", "Proyector opcional"], "concepts": [["Presentación", "Conjunto de diapositivas para comunicar información de forma visual y ordenada."], ["El programa", "Puedes usar un programa de presentaciones o el taller de esta página."], ["Crear diapositivas", "Abre el programa, elige un diseño, escribe un título, agrega texto e imágenes y guarda."], ["Diseñar", "Usa texto claro y breve. Cada diapositiva comunica una idea. Cuida tamaño y contraste."], ["Personalizar", "Puedes agregar colores, formas e imágenes. Las transiciones son opcionales."], ["Presentar", "Revisa tu archivo y practica cómo explicarás cada diapositiva."]], "steps": ["Elige un tema de tu interés: animales, escuela o deportes.", "Crea al menos cuatro diapositivas.", "Incluye un título, texto e imágenes.", "Usa un diseño atractivo y fácil de leer.", "Guarda tu trabajo y practica tu exposición."], "questions": ["¿Para qué sirve una presentación?", "¿Cuándo la usarías?", "¿Qué tema te gustaría presentar?", "¿Qué hace una presentación atractiva?", "¿Qué aprendiste al crearla?"], "learned": ["Conozco qué es una presentación.", "Creo diapositivas con texto e imágenes.", "Uso herramientas de diseño.", "Guardo el trabajo.", "Comunico mis ideas."], "home": "", "practice": "Mi primera presentación", "kind": "slides", "extra": "", "quiz": [], "evidence": "Presentación de al menos cuatro diapositivas."}];
