window.ORIGINAL_GUIDES={"2": {"title": "Entrada, proceso y salida", "subtitle": "Comprender cómo viaja la información dentro de un sistema digital mediante ejemplos concretos y situaciones de la vida cotidiana.", "purpose_title": "Que el alumno comprenda la computadora como un sistema que recibe, transforma y devuelve información.", "purpose_body": "Al finalizar, deberá identificar ejemplos de entrada, proceso y salida sin limitarse a memorizar definiciones.", "evidence_title": "Diagrama Entrada → Proceso → Salida", "evidence_body": "Más una explicación oral de un ejemplo cotidiano.", "objectives": [["Reconocer entradas", "Identificar teclado, mouse, micrófono, cámara y otros medios que introducen información."], ["Comprender el proceso", "Explicar que la computadora sigue instrucciones y transforma datos para producir un resultado."], ["Identificar salidas", "Relacionar monitor, bocinas e impresora con información que la computadora devuelve."]], "prior": ["Qué componentes físicos recuerda de la clase anterior.", "Qué ocurre cuando escribe una letra y ésta aparece en la pantalla.", "Qué cree que pasa dentro del equipo después de hacer clic.", "Ejemplos de aparatos que reciben información y responden."], "materials": ["Computadora o proyector.", "Tarjetas con acciones: escribir, hablar, escuchar, imprimir, tomar foto, mostrar imagen.", "Tres carteles: ENTRADA, PROCESO y SALIDA.", "Hoja con flechas Entrada → Proceso → Salida."], "timeline": [["0–8 min", "Inicio", "Recuperar la clase anterior", "Pregunta: “Si escribo la letra A, ¿cómo sabe la computadora qué debe mostrar?” Escucha hipótesis sin corregir de inmediato."], ["8–18 min", "Modelado", "Representar el flujo", "Escribe una letra con el teclado y muestra el resultado. Señala: teclado = entrada; instrucciones internas = proceso; monitor = salida."], ["18–32 min", "Actividad central", "Juego de clasificación", "El grupo coloca tarjetas bajo Entrada, Proceso o Salida y justifica cada decisión."], ["32–45 min", "Aplicación", "Resolver situaciones", "Analizan casos: videollamada, escuchar música, imprimir una tarea y tomar una fotografía."], ["45–55 min", "Reto individual", "Dibujar un flujo", "Cada alumno crea un ejemplo propio con tres pasos y flechas."], ["55–60 min", "Cierre", "Explicar con una frase", "Completa: “Una computadora recibe…, después…, y finalmente…”."]], "scripts": [["1. Entrada", "“Entrada es la información que le damos a la computadora. Puede entrar con el teclado, el mouse, la cámara o el micrófono.”"], ["2. Proceso", "“Procesar significa trabajar con la información siguiendo instrucciones. No vemos todo lo que ocurre dentro, pero sí podemos observar el resultado.”"], ["3. Salida", "“Salida es la respuesta que recibimos: una imagen, un sonido, una hoja impresa o cualquier resultado que el equipo nos muestra.”"], ["4. Ejemplo completo", "“Escribo 2 + 3: el teclado envía la información, el programa realiza la operación y la pantalla muestra 5.”"]], "steps": [["Observar una demostración", "Seguir el recorrido de una acción simple desde el teclado hasta la pantalla."], ["Clasificar tarjetas", "Decidir si cada elemento o acción corresponde a entrada, proceso o salida."], ["Justificar", "Explicar al menos tres decisiones usando “porque…”"], ["Resolver casos", "Identificar el flujo en una videollamada, una canción o una impresión."], ["Crear un diagrama", "Representar un caso propio con flechas."], ["Explicar", "Compartir oralmente su diagrama con un compañero."]], "questions": [["diagnostic", "Cuando presionas una tecla, ¿qué ocurre antes de que aparezca la letra?", "Explora ideas previas sobre el procesamiento."], ["diagnostic", "¿El monitor manda información o nos la muestra?", "Distingue entrada y salida."], ["process", "En una videollamada, ¿qué función tiene el micrófono? ¿Y las bocinas?", "Relaciona dispositivos con flujo de información."], ["process", "¿La computadora “piensa” igual que una persona cuando procesa?", "Aclara que sigue instrucciones y operaciones."], ["process", "Si una impresora saca una hoja, ¿es entrada o salida? ¿Por qué?", "Exige justificar la categoría."], ["closing", "Inventa un ejemplo de entrada, proceso y salida que no hayamos usado.", "Comprueba transferencia."], ["closing", "¿Puede un mismo dispositivo participar en más de una etapa?", "Abre la idea de dispositivos mixtos."]], "misconceptions": [["“Proceso significa esperar.”", "Aclara que proceso es transformar o trabajar con información."], ["“El monitor es entrada porque lo veo.”", "Diferencia observar información de enviarla al sistema."], ["“La computadora entiende por sí sola.”", "Recalca que ejecuta instrucciones programadas."], ["“Todo lo que se conecta es entrada.”", "Contrasta teclado/micrófono con bocinas/monitor."]], "rubric": [["Clasifica entradas", "Identifica 3 o más correctamente.", "Identifica 2 con apoyo.", "Confunde la mayoría."], ["Reconoce proceso", "Explica que se siguen instrucciones para transformar datos.", "Da una explicación parcial.", "Lo confunde con entrada o salida."], ["Clasifica salidas", "Identifica monitor, bocinas o impresora y explica su función.", "Identifica con preguntas guía.", "No diferencia salida de entrada."], ["Representa el flujo", "Construye un diagrama coherente.", "El diagrama necesita una corrección.", "No logra ordenar las etapas."]], "supports": ["Usar flechas grandes y pictogramas.", "Representar físicamente el flujo con tres alumnos: entrada, proceso y salida.", "Permitir explicar oralmente antes de escribir.", "Repetir casos con objetos familiares."], "challenge": ["Analizar una pantalla táctil y decidir por qué puede funcionar como entrada y salida.", "Diseñar un sistema simple para una máquina expendedora: ¿qué entra y qué sale?"], "evidence": ["Diagrama Entrada → Proceso → Salida.", "Una justificación oral o escrita.", "Clasificación de al menos seis tarjetas."], "home": ["Elegir un dispositivo en casa.", "Escribir qué información recibe.", "Anotar qué resultado entrega."]}, "3": {"title": "Mouse y ventanas", "subtitle": "Desarrollar precisión motriz y autonomía básica para interactuar con la interfaz gráfica de una computadora.", "purpose_title": "Que el alumno controle el puntero con intención y comprenda las acciones básicas de una ventana.", "purpose_body": "Al finalizar, deberá distinguir clic, doble clic, arrastrar y desplazamiento, además de reconocer minimizar, maximizar, mover y cerrar una ventana.", "evidence_title": "Circuito de precisión completado", "evidence_body": "Con registro de las acciones que realizó correctamente.", "objectives": [["Controlar el puntero", "Mover el mouse con precisión y ubicar el cursor sobre objetivos pequeños."], ["Diferenciar acciones", "Usar clic, doble clic y arrastrar según la tarea."], ["Manejar ventanas", "Reconocer y utilizar minimizar, maximizar, mover y cerrar."]], "prior": ["Qué función del mouse recuerda.", "Cómo abre normalmente una aplicación.", "Si alguna vez ha movido una ventana.", "Qué ocurre cuando hace doble clic demasiado rápido o demasiado lento."], "materials": ["Computadora por alumno o pareja.", "Actividad HTML o archivo con objetivos para hacer clic y arrastrar.", "Proyector para modelado.", "Ficha de observación con cuatro acciones."], "timeline": [["0–7 min", "Inicio", "Explorar movimientos", "Pide mover el puntero a cuatro esquinas sin hacer clic. Observa postura y control."], ["7–17 min", "Modelado", "Clic, doble clic y arrastre", "Demuestra cada acción lentamente y verbaliza cuándo se usa."], ["17–32 min", "Práctica guiada", "Circuito de precisión", "Los alumnos completan objetivos de clic, doble clic y arrastre."], ["32–44 min", "Ventanas", "Mover y cambiar tamaño", "Practican minimizar, maximizar, restaurar y mover una ventana."], ["44–55 min", "Reto", "Secuencia sin ayuda", "Abrir una aplicación, moverla, cambiar su tamaño y cerrarla."], ["55–60 min", "Cierre", "Explicar diferencias", "Cada alumno explica una diferencia entre clic y doble clic."]], "scripts": [["1. Clic", "“Un clic sirve para seleccionar o activar un control. No golpeamos el mouse; presionamos una vez y soltamos.”"], ["2. Doble clic", "“Son dos clics seguidos, casi con el mismo ritmo. Se usa en algunos sistemas para abrir archivos o carpetas.”"], ["3. Arrastrar", "“Primero presiono, mantengo presionado, muevo el mouse y después suelto.”"], ["4. Ventanas", "“Una ventana es un espacio de trabajo. Podemos moverla, minimizarla, maximizarla o cerrarla sin apagar toda la computadora.”"]], "steps": [["Calibrar el movimiento", "Mover el puntero siguiendo una ruta sin hacer clic."], ["Clic preciso", "Seleccionar objetivos de diferentes tamaños."], ["Doble clic", "Abrir elementos indicados por el docente."], ["Arrastrar", "Mover figuras a zonas destino."], ["Manejar una ventana", "Minimizar, restaurar, maximizar y mover."], ["Reto autónomo", "Completar una secuencia de acciones sin indicaciones paso a paso."]], "questions": [["diagnostic", "¿Qué diferencia crees que hay entre un clic y un doble clic?", "Explora experiencia previa."], ["process", "¿Qué pasa si sueltas el botón antes de terminar de arrastrar?", "Hace visible la secuencia motriz."], ["process", "¿Cerrar una ventana es lo mismo que apagar la computadora?", "Diferencia aplicación y sistema."], ["process", "¿Para qué podría servir minimizar una ventana?", "Relaciona control con organización."], ["closing", "Explícame cómo arrastrarías un archivo sin hacerlo tú.", "Evalúa lenguaje procedural."], ["closing", "¿Qué acción te resultó más difícil y qué hiciste para mejorar?", "Metacognición."]], "misconceptions": [["“Más fuerza hace que el mouse funcione mejor.”", "Trabaja movimientos suaves y controlados."], ["“Doble clic significa mantener presionado.”", "Practica el ritmo con dos golpes suaves sobre la mesa."], ["“Cerrar una ventana apaga el equipo.”", "Demuestra la diferencia entre cerrar programa y apagar sistema."], ["“Arrastrar es mover sin presionar.”", "Repite la secuencia: presionar, mantener, mover, soltar."]], "rubric": [["Clic preciso", "Selecciona objetivos sin errores repetidos.", "Comete pocos errores.", "Necesita guía constante."], ["Doble clic", "Lo ejecuta con ritmo adecuado.", "Lo logra tras varios intentos.", "No distingue la acción."], ["Arrastre", "Mantiene presionado hasta llegar al destino.", "Suelta antes algunas veces.", "No completa la secuencia."], ["Ventanas", "Maneja 3 o más controles correctamente.", "Maneja 1–2 con ayuda.", "Confunde los controles."]], "supports": ["Aumentar temporalmente el tamaño de los objetivos.", "Reducir la velocidad del puntero si es necesario.", "Permitir mouse externo en vez de trackpad.", "Dar práctica adicional sin límite de tiempo."], "challenge": ["Completar el circuito usando objetivos más pequeños.", "Organizar dos ventanas lado a lado para comparar información."], "evidence": ["Circuito completado.", "Demostración de cuatro acciones.", "Autoevaluación de la acción más difícil."], "home": ["Explicar a un familiar la diferencia entre clic, doble clic y arrastrar.", "Observar en qué aplicaciones se usa cada acción."]}, "4": {"title": "Teclado I", "subtitle": "Familiarizarse con la distribución del teclado y escribir textos breves usando letras, números y teclas esenciales.", "purpose_title": "Que el alumno escriba con intención y comprenda que cada tecla tiene una función.", "purpose_body": "La meta no es velocidad todavía: primero buscamos orientación, precisión, postura y uso correcto de espacio, Enter, borrar y mayúsculas.", "evidence_title": "Texto breve correctamente escrito", "evidence_body": "Nombre, una oración y una línea con números usando las teclas estudiadas.", "objectives": [["Ubicar grupos de teclas", "Reconocer letras, números y teclas funcionales básicas."], ["Escribir con precisión", "Teclear palabras cortas respetando espacios."], ["Usar teclas esenciales", "Aplicar Enter, Retroceso/Borrar y Mayúsculas según la necesidad."]], "prior": ["Cómo escribe normalmente en un teléfono.", "Qué teclas reconoce de vista.", "Para qué cree que sirve la barra espaciadora.", "Qué hace cuando se equivoca al escribir."], "materials": ["Computadora con editor de texto.", "Teclado proyectado o impreso.", "Actividad de mecanografía simple.", "Ficha con nombre, oración y números."], "timeline": [["0–8 min", "Inicio", "Mapa del teclado", "Identifican letras, números, espacio, Enter y borrar en un teclado grande."], ["8–18 min", "Modelado", "Postura y funciones", "Demuestra posición cómoda de manos y uso de teclas sin golpear."], ["18–33 min", "Práctica", "Palabras y espacios", "Escriben palabras del salón y su nombre completo."], ["33–45 min", "Aplicación", "Enter, borrar y mayúsculas", "Corrigen errores y crean dos líneas separadas."], ["45–55 min", "Reto", "Mini texto", "Escriben una oración de 8–12 palabras y una línea con números."], ["55–60 min", "Cierre", "Revisión consciente", "Comparan su texto con el modelo y corrigen por sí mismos."]], "scripts": [["1. Orientación", "“No necesitamos memorizar todo el teclado hoy. Primero aprenderemos a encontrar grupos de teclas.”"], ["2. Espacio", "“La barra espaciadora separa palabras. Un espacio es suficiente.”"], ["3. Enter", "“Enter nos ayuda a comenzar una nueva línea o confirmar algunas acciones, según el programa.”"], ["4. Borrar y mayúsculas", "“Borrar corrige; Shift o Mayúsculas nos permiten escribir una letra en mayúscula cuando lo necesitamos.”"]], "steps": [["Localizar", "Señalar letras, números, espacio, Enter y borrar."], ["Escribir el nombre", "Teclear nombre y apellido con un solo espacio entre palabras."], ["Copiar palabras", "Escribir cinco palabras del entorno escolar."], ["Corregir", "Detectar y borrar errores intencionales."], ["Crear dos líneas", "Usar Enter para separar dos ideas."], ["Mini texto", "Escribir una oración y revisarla antes de levantar la mano."]], "questions": [["diagnostic", "¿Qué haces en el teclado cuando te equivocas?", "Explora hábitos previos."], ["process", "¿Por qué no debemos dejar muchos espacios entre palabras?", "Relaciona función y legibilidad."], ["process", "¿Enter siempre significa “enviar”?", "Evita una generalización incorrecta."], ["process", "¿Qué opción usarías para escribir sólo una letra mayúscula?", "Comprueba uso de Shift."], ["closing", "¿Qué tecla te ayudó más hoy y por qué?", "Metacognición funcional."], ["closing", "¿Qué es más importante hoy: escribir rápido o escribir correctamente?", "Refuerza precisión antes que velocidad."]], "misconceptions": [["“Hay que escribir muy rápido.”", "Prioriza precisión y control."], ["“Enter siempre manda un mensaje.”", "Explica que depende del programa."], ["“Borrar y Supr son exactamente iguales.”", "A nivel inicial basta explicar que ambas eliminan, pero pueden hacerlo en direcciones distintas."], ["“Mayúsculas se usa para toda palabra importante.”", "Relaciona mayúscula con inicio de oración y nombres propios."]], "rubric": [["Ubica teclas", "Encuentra las teclas esenciales sin ayuda.", "Encuentra la mayoría con apoyo.", "Necesita guía continua."], ["Precisión", "Escribe con pocos errores.", "Comete varios errores pero corrige.", "No detecta errores aún."], ["Espaciado", "Usa un espacio entre palabras.", "Presenta inconsistencias menores.", "Usa espacios múltiples o ninguno."], ["Uso funcional", "Aplica Enter, borrar y mayúsculas correctamente.", "Aplica 2 de 3 con ayuda.", "Confunde sus funciones."]], "supports": ["Usar teclado impreso con colores por zonas.", "Reducir la cantidad de texto.", "Permitir búsqueda visual lenta sin presión de tiempo.", "Trabajar en pareja para localizar teclas, pero escribir individualmente."], "challenge": ["Escribir una oración sin mirar el modelo durante 20 segundos.", "Localizar rápidamente las letras de su nombre sin escribirlas."], "evidence": ["Nombre completo.", "Una oración de 8–12 palabras.", "Uso visible de Enter y corrección de un error."], "home": ["Identificar en un teclado real o imagen cinco teclas vistas en clase.", "Explicar a alguien para qué sirve Enter y la barra espaciadora."]}, "5": {"title": "Teclado II", "subtitle": "Ampliar el uso del teclado con signos, acentos, mayúsculas y atajos sencillos de edición.", "purpose_title": "Que el alumno pase de “teclear letras” a editar un texto con intención.", "purpose_body": "Al finalizar, deberá corregir un texto corto usando signos, acentos y algunos atajos básicos sin perder de vista el contenido.", "evidence_title": "Texto corregido y mejorado", "evidence_body": "Con signos, acentos y al menos un atajo utilizado correctamente.", "objectives": [["Escribir signos básicos", "Localizar punto, coma, signos de interrogación y otros caracteres frecuentes."], ["Incorporar acentos", "Escribir palabras acentuadas con apoyo del teclado."], ["Usar atajos sencillos", "Aplicar copiar, pegar, deshacer o seleccionar cuando sea pertinente."]], "prior": ["Qué teclas esenciales usaron en la clase anterior.", "Dónde han visto signos de interrogación y punto.", "Qué hacen cuando borran algo por accidente.", "Si conocen alguna combinación de teclas."], "materials": ["Editor de texto.", "Texto breve con errores intencionales.", "Teclado proyectado.", "Tarjeta de apoyo con 3–4 atajos."], "timeline": [["0–8 min", "Inicio", "Detectar errores", "Proyecta un texto sin signos ni acentos y pregunta qué dificulta su lectura."], ["8–20 min", "Modelado", "Signos y acentos", "Demuestra cómo localizar los caracteres en el teclado disponible."], ["20–32 min", "Práctica", "Corrección guiada", "El grupo corrige una primera oración paso a paso."], ["32–45 min", "Atajos", "Deshacer, copiar y pegar", "Muestra sólo atajos útiles y explica su propósito."], ["45–55 min", "Reto individual", "Editar un párrafo", "Cada alumno corrige un texto breve con una lista de verificación."], ["55–60 min", "Cierre", "Leer y comparar", "Leen antes/después y explican qué cambió."]], "scripts": [["1. Los signos ayudan a entender", "“El teclado no sólo sirve para letras. Los signos nos ayudan a que el lector sepa dónde termina una idea o cuándo estamos preguntando.”"], ["2. Acentos", "“El acento escrito forma parte de la palabra. Primero localizamos la tecla y luego seguimos el procedimiento del teclado que estamos usando.”"], ["3. Atajos", "“Un atajo no es magia: es una combinación que ordena al programa hacer algo rápidamente.”"], ["4. Deshacer", "“Ctrl/Cmd + Z es como decir: ‘regresa un paso’. Nos ayuda cuando cometemos un error al editar.”"]], "steps": [["Leer primero", "Leer el texto completo antes de tocar el teclado."], ["Marcar problemas", "Identificar palabras o lugares donde faltan signos."], ["Corregir signos", "Agregar punto, coma o interrogación según el sentido."], ["Corregir acentos", "Editar palabras seleccionadas."], ["Usar un atajo", "Aplicar deshacer, copiar o pegar en un ejercicio controlado."], ["Releer", "Comprobar si ahora el texto se entiende mejor."]], "questions": [["diagnostic", "¿Qué cambia si escribo una pregunta sin signos?", "Relaciona forma y significado."], ["process", "¿Por qué conviene leer antes de empezar a corregir?", "Promueve edición consciente."], ["process", "¿Qué harías si borras una oración por accidente?", "Introduce deshacer."], ["process", "¿Copiar y pegar significa que ya entendimos el texto?", "Distingue herramienta y comprensión."], ["closing", "¿Qué corrección hizo que el texto fuera más fácil de entender?", "Evalúa intención comunicativa."], ["closing", "¿Qué atajo recordarás y para qué sirve?", "Comprueba uso funcional."]], "misconceptions": [["“Los signos sólo decoran.”", "Muestra cómo cambian el significado y la lectura."], ["“Deshacer borra todo.”", "Demuestra que revierte acciones paso a paso."], ["“Copiar y pegar evita tener que leer.”", "Insiste en comprender antes de reutilizar texto."], ["“Todos los teclados tienen los signos en el mismo lugar.”", "Explica que la distribución puede variar."]], "rubric": [["Signos", "Corrige los signos principales correctamente.", "Corrige la mayoría con apoyo.", "No identifica dónde faltan."], ["Acentos", "Escribe las palabras indicadas correctamente.", "Necesita apoyo visual.", "Evita o elimina los acentos."], ["Atajo", "Usa al menos un atajo con propósito.", "Lo ejecuta con guía.", "No relaciona combinación y acción."], ["Revisión", "Relee y mejora su texto.", "Relee sólo cuando se le pide.", "Entrega sin revisar."]], "supports": ["Tarjeta visual de teclas y atajos.", "Texto más corto para quien lo requiera.", "Permitir corrección por etapas.", "No penalizar velocidad."], "challenge": ["Corregir un texto con errores no señalados.", "Usar copiar/pegar para reorganizar dos oraciones y explicar el nuevo orden."], "evidence": ["Párrafo corregido.", "Lista de verificación completada.", "Uso de al menos un atajo."], "home": ["Observar un texto digital y encontrar tres signos diferentes.", "Preguntar a un familiar qué atajo de teclado usa y para qué."]}, "6": {"title": "Archivos y carpetas", "subtitle": "Aprender a guardar, nombrar, encontrar y organizar trabajos digitales de forma ordenada.", "purpose_title": "Que el alumno comprenda que organizar archivos es parte del trabajo digital, no un detalle opcional.", "purpose_body": "Al finalizar, deberá crear una carpeta, guardar un archivo con un nombre claro y volver a localizarlo sin depender del docente.", "evidence_title": "Carpeta de trabajo organizada", "evidence_body": "Con estructura simple y archivos nombrados de manera comprensible.", "objectives": [["Comprender archivo y carpeta", "Diferenciar un documento guardado de la carpeta que lo contiene."], ["Nombrar con criterio", "Usar nombres breves y descriptivos."], ["Guardar y recuperar", "Seleccionar una ubicación y volver a abrir el archivo."]], "prior": ["Dónde creen que “vive” un trabajo después de guardarlo.", "Qué pasa si varios archivos se llaman Documento1.", "Cómo organizan cuadernos o útiles en la vida real.", "Si han usado carpetas en teléfono o computadora."], "materials": ["Computadora con administrador de archivos.", "Tres archivos de práctica.", "Proyector.", "Ficha con una estructura de carpetas sencilla."], "timeline": [["0–8 min", "Inicio", "Analogía con útiles", "Compara una mochila desordenada con una carpeta digital sin organización."], ["8–20 min", "Modelado", "Archivo, carpeta y ruta", "Crea una carpeta y guarda un archivo mostrando cada decisión."], ["20–35 min", "Práctica guiada", "Crear estructura", "Los alumnos crean una carpeta principal y dos subcarpetas simples."], ["35–48 min", "Reto", "Guardar y encontrar", "Guardan un archivo, cierran el programa y vuelven a localizarlo."], ["48–56 min", "Organización", "Renombrar correctamente", "Corrigen nombres como Documento1 o Nuevoarchivo."], ["56–60 min", "Cierre", "Explicar una regla", "Cada alumno propone una regla para no perder archivos."]], "scripts": [["1. Archivo", "“Un archivo es un trabajo guardado: puede ser un texto, una imagen, una presentación u otro tipo de contenido.”"], ["2. Carpeta", "“Una carpeta sirve para reunir archivos relacionados, igual que una carpeta física reúne hojas.”"], ["3. Nombre claro", "“Un buen nombre nos dice qué contiene el archivo sin tener que abrirlo.”"], ["4. Guardar no es memorizar", "“La computadora necesita saber en qué lugar guardaremos el archivo. Si no sabemos dónde, después será difícil recuperarlo.”"]], "steps": [["Crear carpeta principal", "Nombrarla Computación_4A o equivalente indicado."], ["Crear subcarpetas", "Por ejemplo Actividades y Proyectos."], ["Guardar un archivo", "Elegir la carpeta correcta y un nombre descriptivo."], ["Cerrar y recuperar", "Cerrar el programa y abrir el archivo desde su ubicación."], ["Renombrar", "Cambiar un nombre confuso por otro más claro."], ["Explicar la organización", "Mostrar a un compañero dónde guardó su trabajo y por qué."]], "questions": [["diagnostic", "¿Qué pasaría si todos tus trabajos se llamaran Documento1?", "Hace visible la necesidad de nombrar."], ["process", "¿Cuál es la diferencia entre una carpeta y un archivo?", "Comprueba concepto central."], ["process", "¿Qué nombre es mejor: tarea.docx o Animales_Veracruz.docx? ¿Por qué?", "Promueve criterios de nomenclatura."], ["process", "Si guardaste el archivo pero no recuerdas dónde, ¿qué estrategias usarías?", "Trabaja recuperación."], ["closing", "¿Qué regla usarás desde hoy para organizar tus trabajos?", "Construye hábito."], ["closing", "Explícame cómo encontrarías tu archivo mañana.", "Evalúa memoria procedural."]], "misconceptions": [["“Guardar y descargar son lo mismo.”", "Aclara que ambos crean/copían archivos, pero parten de acciones distintas."], ["“Si cierro el programa, el archivo desaparece.”", "Diferencia archivo guardado y aplicación abierta."], ["“La carpeta contiene el programa.”", "Usa ejemplos visuales de carpeta y archivo."], ["“Puedo poner cualquier nombre y luego recordaré.”", "Compara varios nombres genéricos para mostrar el problema."]], "rubric": [["Crea carpeta", "Crea y nombra correctamente.", "Lo hace con guía.", "No distingue carpeta de archivo."], ["Guarda archivo", "Selecciona ubicación correcta.", "Necesita recordatorio.", "Guarda en ubicación desconocida."], ["Nombra", "Usa nombre descriptivo.", "Nombre comprensible pero poco específico.", "Usa nombre genérico."], ["Recupera", "Encuentra y abre sin ayuda.", "Encuentra con una pista.", "No recuerda la ubicación."]], "supports": ["Entregar una ruta visual paso a paso.", "Usar sólo una carpeta principal antes de introducir subcarpetas.", "Permitir repetir el ciclo guardar-cerrar-abrir.", "Mantener nombres cortos y legibles."], "challenge": ["Diseñar una estructura para organizar tareas de varias materias.", "Proponer una convención de nombres con fecha o tema."], "evidence": ["Carpeta principal creada.", "Archivo con nombre descriptivo.", "Demostración de recuperación."], "home": ["Dibujar cómo organizaría digitalmente tres materias.", "Proponer tres buenos nombres de archivo para tareas distintas."]}, "7": {"title": "Procesador de textos I", "subtitle": "Crear una ficha informativa breve aplicando estructura, formato y decisiones básicas de legibilidad.", "purpose_title": "Que el alumno entienda que dar formato sirve para organizar ideas, no para decorar todo.", "purpose_body": "Al finalizar, deberá producir una ficha con título, párrafo y formato básico coherente.", "evidence_title": "Ficha informativa digital", "evidence_body": "Título, párrafo legible y uso moderado de negritas o alineación.", "objectives": [["Organizar texto", "Diferenciar título y cuerpo."], ["Aplicar formato", "Usar tamaño, negrita y alineación con intención."], ["Revisar legibilidad", "Comprobar que el documento se lea con facilidad."]], "prior": ["Qué hace que un título parezca título.", "Qué ocurre si todo está en negritas.", "Qué documentos han visto con título y párrafos.", "Cómo saben dónde empieza una idea nueva."], "materials": ["Procesador de textos disponible.", "Modelo de ficha informativa.", "Texto breve sobre un tema conocido.", "Lista de cotejo visual."], "timeline": [["0–8 min", "Inicio", "Comparar dos documentos", "Muestra uno ordenado y otro saturado. Pregunta cuál se entiende primero y por qué."], ["8–18 min", "Modelado", "Jerarquía básica", "Escribe título y párrafo y demuestra tamaño, negrita y alineación."], ["18–35 min", "Práctica", "Construir la ficha", "Los alumnos escriben o copian un texto breve y crean el título."], ["35–48 min", "Formato", "Aplicar sólo lo necesario", "Ajustan tamaño, negrita y alineación siguiendo criterios."], ["48–56 min", "Revisión", "Intercambio por parejas", "Un compañero verifica legibilidad y jerarquía."], ["56–60 min", "Cierre", "Una decisión de diseño", "Cada alumno explica por qué formateó una parte de cierta manera."]], "scripts": [["1. Jerarquía", "“El lector necesita saber qué mirar primero. El título debe destacar más que el párrafo.”"], ["2. Tamaño", "“Más grande no siempre significa mejor. Usamos tamaños diferentes para mostrar importancia.”"], ["3. Negrita", "“La negrita sirve para destacar algo importante. Si todo está en negrita, nada destaca.”"], ["4. Alineación", "“La alineación ordena el texto. Para párrafos largos suele ser más fácil leer desde un mismo borde izquierdo.”"]], "steps": [["Crear título", "Escribir un título claro relacionado con el tema."], ["Escribir párrafo", "Redactar o transcribir 3–5 oraciones."], ["Dar jerarquía", "Ajustar tamaño y peso del título."], ["Revisar alineación", "Elegir una alineación apropiada."], ["Usar negrita con moderación", "Destacar sólo palabras necesarias."], ["Revisar", "Comprobar ortografía básica, espaciado y legibilidad."]], "questions": [["diagnostic", "¿Qué miras primero cuando abres una página: el título o el párrafo? ¿Por qué?", "Introduce jerarquía."], ["process", "¿Qué pasaría si el título fuera más pequeño que el texto?", "Relaciona formato con lectura."], ["process", "¿Por qué no conviene poner todo en negritas?", "Refuerza uso intencional."], ["process", "¿Qué parte necesita más espacio alrededor?", "Trabaja respiración visual."], ["closing", "¿Qué decisión de formato ayuda más a entender tu ficha?", "Evalúa razonamiento de diseño."], ["closing", "¿Qué cambiarías si el texto fuera para un niño más pequeño?", "Promueve adaptación al lector."]], "misconceptions": [["“Mientras más grande, más bonito.”", "Vuelve a propósito y jerarquía."], ["“Todo debe ir centrado.”", "Compara lectura de párrafos centrados y alineados a la izquierda."], ["“Negrita = importante siempre.”", "Selecciona sólo conceptos clave."], ["“Formato y contenido son lo mismo.”", "Distingue qué dice el texto y cómo se presenta."]], "rubric": [["Título", "Es claro y visualmente dominante.", "Existe pero compite con el párrafo.", "No se distingue."], ["Párrafo", "Es legible y ordenado.", "Presenta detalles menores.", "La lectura es difícil."], ["Formato", "Usa tamaño/negrita con intención.", "Usa formato parcialmente.", "Aplica formato de forma aleatoria."], ["Revisión", "Corrige después de recibir retroalimentación.", "Corrige sólo una parte.", "No revisa."]], "supports": ["Entregar plantilla con título y cuerpo ya delimitados.", "Ofrecer sólo dos tamaños recomendados.", "Usar texto corto.", "Permitir dictado al docente o compañero si la escritura es una barrera adicional."], "challenge": ["Crear dos versiones de la misma ficha para públicos distintos.", "Explicar qué cambió y por qué."], "evidence": ["Ficha digital guardada.", "Lista de cotejo.", "Explicación de una decisión de formato."], "home": ["Observar una página de libro o cartel y señalar título y cuerpo.", "Escribir qué elemento se ve primero y por qué."]}, "8": {"title": "Procesador de textos II", "subtitle": "Integrar imágenes y pies de imagen sin perder claridad, relación con el tema ni legibilidad.", "purpose_title": "Que el alumno use imágenes como información, no como decoración sin propósito.", "purpose_body": "Al finalizar, deberá insertar una imagen pertinente, ajustar su tamaño y escribir un pie que explique qué muestra o por qué es importante.", "evidence_title": "Página informativa con imagen", "evidence_body": "Texto, imagen pertinente y pie de imagen con relación clara.", "objectives": [["Insertar imagen", "Agregar una imagen en el documento."], ["Ajustar presentación", "Modificar tamaño y ubicación sin deformarla."], ["Relacionar texto e imagen", "Escribir un pie que aporte información."]], "prior": ["Qué diferencia hay entre una imagen útil y una decorativa.", "Qué recuerdan sobre títulos y párrafos.", "Qué pasa cuando una imagen es demasiado grande.", "Dónde han visto pies de foto."], "materials": ["Procesador de textos.", "Carpeta con 4–6 imágenes seleccionadas por el docente.", "Ficha de la clase anterior.", "Modelo con buen y mal uso de imagen."], "timeline": [["0–8 min", "Inicio", "¿Qué imagen ayuda más?", "Compara dos imágenes y pregunta cuál comunica mejor el tema."], ["8–20 min", "Modelado", "Insertar y redimensionar", "Demuestra inserción, esquinas para mantener proporción y ubicación."], ["20–35 min", "Práctica", "Elegir imagen pertinente", "Cada alumno selecciona una imagen de un conjunto controlado."], ["35–47 min", "Integración", "Añadir pie de imagen", "Escriben una frase que explique la imagen."], ["47–56 min", "Revisión", "Texto + imagen", "Comprueban que ningún elemento tape o dificulte la lectura."], ["56–60 min", "Cierre", "Justificar selección", "Explican por qué esa imagen ayuda al lector."]], "scripts": [["1. Imagen pertinente", "“Una imagen debe ayudar a entender el tema. No la elegimos sólo porque sea bonita.”"], ["2. Tamaño", "“Si hacemos una imagen demasiado grande, puede quitar espacio al texto. Si es demasiado pequeña, quizá no se entienda.”"], ["3. Proporción", "“Al cambiar el tamaño debemos conservar su forma para no estirarla.”"], ["4. Pie de imagen", "“El pie explica qué vemos o por qué esa imagen es importante para el texto.”"]], "steps": [["Releer la ficha", "Recordar cuál es la idea principal."], ["Seleccionar imagen", "Elegir la que mejor represente el contenido."], ["Insertar", "Agregarla usando la herramienta correspondiente."], ["Redimensionar", "Ajustar desde una esquina sin deformar."], ["Ubicar", "Colocarla sin tapar texto."], ["Escribir pie", "Añadir una frase informativa breve."]], "questions": [["diagnostic", "¿Toda imagen hace que un documento sea mejor?", "Explora criterio visual."], ["process", "¿Cómo sabes si una imagen tiene relación con el tema?", "Promueve pertinencia."], ["process", "¿Qué ocurre si estiramos sólo un lado de la imagen?", "Introduce proporción."], ["process", "¿Qué debe decir un buen pie de imagen?", "Relaciona imagen y texto."], ["closing", "¿Qué aprendería el lector gracias a tu imagen?", "Evalúa función comunicativa."], ["closing", "Si quitaras la imagen, ¿qué información se perdería?", "Comprueba valor real."]], "misconceptions": [["“Más imágenes siempre es mejor.”", "Prioriza pertinencia sobre cantidad."], ["“Una imagen puede tapar texto.”", "Revisa flujo y legibilidad."], ["“El pie sólo repite lo obvio.”", "Pide añadir contexto o significado."], ["“Cualquier imagen de Internet se puede usar sin pensar.”", "Introduce de forma inicial la importancia de origen y uso responsable."]], "rubric": [["Pertinencia", "La imagen apoya claramente el tema.", "Tiene relación parcial.", "No se relaciona."], ["Tamaño", "Es visible sin dominar la página.", "Requiere ajuste menor.", "Dificulta la lectura."], ["Pie de imagen", "Aporta información clara.", "Describe de forma básica.", "Falta o no corresponde."], ["Integración", "Texto e imagen conviven ordenadamente.", "Hay pequeños problemas.", "Se superponen o compiten."]], "supports": ["Usar un banco de imágenes previamente seleccionado.", "Limitar a una sola imagen.", "Ofrecer pies de imagen incompletos para completar.", "Demostrar redimensionado varias veces."], "challenge": ["Comparar dos imágenes posibles y argumentar cuál comunica mejor.", "Añadir una fuente simple de la imagen si el contexto lo permite."], "evidence": ["Página informativa completa.", "Imagen correctamente ajustada.", "Pie de imagen pertinente."], "home": ["Buscar en un libro una imagen con pie.", "Explicar qué aporta el pie que no aparece en la imagen."]}, "9": {"title": "Proyecto: cartel digital", "subtitle": "Integrar texto, imagen y jerarquía visual para comunicar un mensaje escolar o comunitario.", "purpose_title": "Que el alumno diseñe para comunicar, no sólo para decorar.", "purpose_body": "Al finalizar, deberá producir un cartel claro con un mensaje principal, información necesaria y una imagen pertinente.", "evidence_title": "Cartel digital terminado", "evidence_body": "Con propósito, jerarquía, imagen pertinente y revisión final.", "objectives": [["Definir propósito", "Decidir qué quiere comunicar y a quién."], ["Construir jerarquía", "Organizar título, mensaje e información secundaria."], ["Integrar recursos", "Usar texto e imagen con equilibrio."]], "prior": ["Qué características tenía una ficha legible.", "Cómo usar una imagen con propósito.", "Qué hace que un cartel llame la atención.", "Qué información sería indispensable en una invitación o campaña."], "materials": ["Procesador de textos, presentaciones o editor simple.", "Banco de imágenes seguro.", "Plantilla opcional.", "Lista de cotejo del cartel."], "timeline": [["0–8 min", "Inicio", "Analizar carteles", "Compara un cartel claro y uno saturado. Pregunta cuál se entiende en cinco segundos."], ["8–18 min", "Planeación", "Mensaje y público", "Cada alumno define tema, destinatario y acción esperada."], ["18–30 min", "Boceto", "Organizar antes de diseñar", "Dibujan distribución rápida en papel."], ["30–47 min", "Producción", "Crear cartel digital", "Construyen título, mensaje, imagen e información secundaria."], ["47–55 min", "Revisión", "Prueba de 5 segundos", "Un compañero observa y dice qué entendió primero."], ["55–60 min", "Cierre", "Ajuste final", "Modifican un elemento según retroalimentación."]], "scripts": [["1. Propósito", "“Antes de elegir colores o imágenes debemos saber qué queremos que la persona entienda o haga.”"], ["2. Jerarquía", "“El título es la puerta de entrada. Después viene el mensaje principal y al final los detalles.”"], ["3. Menos puede comunicar más", "“Si llenamos todos los espacios, el lector no sabe dónde mirar.”"], ["4. Prueba de cinco segundos", "“Un buen cartel permite entender rápidamente de qué trata, aunque después podamos leer más detalles.”"]], "steps": [["Elegir tema", "Seleccionar un asunto escolar o comunitario."], ["Definir público", "Decidir quién leerá el cartel."], ["Escribir mensaje", "Crear una frase principal breve."], ["Bocetar", "Distribuir título, imagen y datos."], ["Diseñar", "Construir la versión digital."], ["Probar y mejorar", "Aplicar la prueba de cinco segundos y corregir."]], "questions": [["diagnostic", "¿Qué debe entender una persona primero al ver tu cartel?", "Centra el propósito."], ["process", "¿Tu título se puede leer rápidamente?", "Revisa jerarquía."], ["process", "¿La imagen ayuda a entender o sólo ocupa espacio?", "Evalúa pertinencia."], ["process", "¿Qué información podrías quitar sin perder el mensaje?", "Reduce saturación."], ["closing", "¿Qué dijo tu compañero que entendió en cinco segundos?", "Comprueba efectividad."], ["closing", "¿Qué cambio mejoró más tu cartel?", "Metacognición de diseño."]], "misconceptions": [["“Un cartel necesita muchos colores.”", "Limita la paleta y prioriza contraste."], ["“Mientras más texto, más información.”", "Enfatiza síntesis."], ["“Todo debe tener el mismo tamaño.”", "Usa jerarquía."], ["“La decoración es el objetivo.”", "Vuelve a mensaje, público y acción."]], "rubric": [["Propósito", "El mensaje es claro y adecuado al público.", "Se entiende parcialmente.", "No queda claro."], ["Jerarquía", "Título y mensaje se distinguen con facilidad.", "Hay competencia entre elementos.", "Todo tiene el mismo peso."], ["Imagen", "Apoya directamente el mensaje.", "Tiene relación general.", "Es decorativa o confusa."], ["Legibilidad", "Se lee con facilidad y buen contraste.", "Presenta pequeños problemas.", "Texto difícil de leer."]], "supports": ["Ofrecer tres temas posibles.", "Usar una plantilla con zonas definidas.", "Limitar fuentes y colores disponibles.", "Permitir dictar el mensaje antes de escribirlo."], "challenge": ["Crear una segunda versión para otro público.", "Justificar qué cambió en jerarquía, lenguaje o imagen."], "evidence": ["Boceto inicial.", "Cartel digital final.", "Retroalimentación de un compañero y cambio aplicado."], "home": ["Mostrar el cartel a un familiar durante cinco segundos.", "Preguntar qué entendió primero y anotar la respuesta."]}, "10": {"title": "¿Qué es Internet?", "subtitle": "Distinguir Internet, web, navegador, buscador y sitio web mediante analogías y ejemplos cercanos.", "purpose_title": "Que el alumno deje de usar “Internet”, “Google” y “navegador” como si fueran exactamente lo mismo.", "purpose_body": "Al finalizar, deberá explicar con ejemplos la función básica de Internet, navegador, buscador y sitio web.", "evidence_title": "Mapa conceptual de Internet", "evidence_body": "Con relaciones claras entre red, navegador, buscador y sitio web.", "objectives": [["Comprender Internet", "Reconocerlo como una red que conecta dispositivos y servicios."], ["Distinguir herramientas", "Diferenciar navegador y buscador."], ["Reconocer sitios y páginas", "Entender que un sitio contiene páginas a las que accedemos mediante un navegador."]], "prior": ["Qué dicen cuando quieren buscar algo en línea.", "Qué aplicaciones usan para navegar.", "Qué entienden por página web.", "Si creen que Google e Internet son lo mismo."], "materials": ["Computadora con navegador; conexión opcional.", "Capturas de pantalla de navegador, buscador y sitio.", "Tarjetas con conceptos.", "Hoja para mapa conceptual."], "timeline": [["0–8 min", "Inicio", "Pregunta provocadora", "Pregunta: “¿Google es Internet?” y registra respuestas."], ["8–20 min", "Analogía", "Ciudad, calles y lugares", "Explica Internet como red de caminos; navegador como vehículo; buscador como guía; sitio como destino."], ["20–32 min", "Demostración", "Observar interfaz", "Señala barra del navegador, página del buscador y un sitio web."], ["32–45 min", "Actividad central", "Ordenar tarjetas", "Los alumnos relacionan términos con definiciones y ejemplos."], ["45–55 min", "Mapa conceptual", "Construir relaciones", "Crean un esquema con flechas y una analogía propia."], ["55–60 min", "Cierre", "Explicar sin memorizar", "Responden: “Para entrar a un sitio web necesito…”"]], "scripts": [["1. Internet", "“Internet es una gran red que permite que muchos dispositivos y servicios se comuniquen.”"], ["2. Navegador", "“El navegador es el programa que usamos para abrir y recorrer sitios web. Ejemplos: Chrome, Safari, Edge o Firefox.”"], ["3. Buscador", "“Un buscador es un servicio que ayuda a localizar páginas o información dentro de la web.”"], ["4. Sitio web", "“Un sitio web es un conjunto de páginas relacionadas que visitamos usando una dirección o enlaces.”"]], "steps": [["Escuchar la analogía", "Relacionar red, vehículo, guía y destino."], ["Identificar", "Observar capturas y señalar navegador, buscador y sitio."], ["Clasificar tarjetas", "Unir concepto, definición y ejemplo."], ["Construir mapa", "Dibujar relaciones con flechas."], ["Crear analogía propia", "Explicar los conceptos con otro ejemplo cotidiano."], ["Compartir", "Comparar mapas con un compañero."]], "questions": [["diagnostic", "¿Google es Internet? ¿Por qué lo crees?", "Detecta confusión común."], ["process", "Si no tienes navegador, ¿cómo abrirías una página web?", "Relaciona herramienta y función."], ["process", "¿Un buscador y un sitio web pueden verse dentro del navegador?", "Comprueba jerarquía conceptual."], ["process", "¿Internet y la web son exactamente lo mismo?", "Introduce que la web es uno de los servicios que funcionan sobre Internet."], ["closing", "Explícame la diferencia entre navegador y buscador con un ejemplo.", "Comprueba comprensión."], ["closing", "¿Qué concepto te confundía antes de la clase?", "Metacognición."]], "misconceptions": [["“Google es Internet.”", "Separa empresa/servicios, buscador e infraestructura de red."], ["“Chrome es un buscador.”", "Aclara que Chrome es navegador; puede abrir distintos buscadores."], ["“Una página web es una aplicación instalada.”", "Contrasta programa local y contenido web."], ["“Sin buscador no existe la web.”", "Explica que podemos entrar a una dirección o enlace directamente."]], "rubric": [["Internet", "Lo explica como red de conexión.", "Tiene idea general pero imprecisa.", "Lo confunde con una app."], ["Navegador", "Identifica función y un ejemplo.", "Identifica con ayuda.", "Lo confunde con buscador."], ["Buscador", "Explica que ayuda a localizar información.", "Da ejemplo sin explicar función.", "Lo considera sinónimo de Internet."], ["Mapa conceptual", "Relaciona correctamente los cuatro conceptos.", "Tiene una relación incorrecta.", "No logra establecer relaciones."]], "supports": ["Usar capturas impresas si no hay conexión.", "Mantener una sola analogía durante toda la clase.", "Dar tarjetas con colores distintos por categoría.", "Permitir explicación oral del mapa."], "challenge": ["Añadir los conceptos enlace, dirección web y servidor de manera introductoria.", "Comparar dos navegadores y dos buscadores sin convertir la clase en una lista de marcas."], "evidence": ["Mapa conceptual.", "Clasificación de tarjetas.", "Explicación oral de navegador vs. buscador."], "home": ["Preguntar qué navegador usan en casa.", "Anotar un sitio web que visitan y un buscador que conocen.", "Explicar a un familiar la diferencia entre navegador y buscador."]}};